INSERT INTO `posts` VALUES (47,33,'xin chào cả nha, tôi muốn tìm hiểu thông tin về đại hội này','uploads/posts/99fa4751-1d69-4a33-b1c8-d522b19ffc5e.png','public','IMAGE',NULL,0,0,0,0,'2026-10-08 08:20:07',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(48,33,'oke bạn nhó',NULL,'public',NULL,NULL,0,1,0,0,'2026-10-08 08:21:02',15,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(49,33,'Tôi muốn tìm việc làm part time!!!',NULL,'public',NULL,NULL,0,0,0,0,'2026-10-08 08:22:14',NULL,10,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(101,1,'Dậy từ 5h sáng chỉ để bắt khoảnh khắc nắng đầu tiên chiếu qua dãy nhà trung tâm. Trường mình buổi sáng sớm yên bình lạ thường, chẳng giống lúc 7h kẹt xe ở cổng chút nào 😄 Chủ nhật này nhóm Nhiếp ảnh đi chụp tiếp, ai muốn đi cùng thì bình luận nhé! #NhiepAnh #HCMUTE #BinhMinh','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P01.jpg','public','IMAGE',NULL,0,9,4,0,'2026-09-02 22:10:27',NULL,9,'ACTIVE',0,'POSITIVE',0.351,'LEXICON',NULL,NULL,NULL),(102,1,'Demo bản hoàn chỉnh hệ thống IoT đo nhiệt độ và độ ẩm phòng học: ESP32 đọc cảm biến rồi đẩy dữ liệu lên server, app điện thoại cập nhật theo thời gian thực. Phòng nào quá 30°C thì app báo ngay. Hai tháng làm đồ án gói gọn trong 2 phút 😅 Source mình để ở bình luận. #IoT #ESP32 #DoAn','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P02.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P02.mp4',119,6,5,0,'2026-09-06 13:09:27',NULL,2,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(103,1,'Combo chạy deadline quen thuộc: một ly cà phê sữa đá, laptop 20% pin và một quán có ổ cắm. Quán này nằm trên đường Võ Văn Ngân, nước 25k, wifi mạnh, ngồi từ trưa tới tối không ai đuổi ☕ #CaPhe #ChayDeadline','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P03.jpg','public','IMAGE',NULL,0,8,4,0,'2026-09-14 08:09:31',NULL,NULL,'ACTIVE',0,'NEUTRAL',-0.243,'LEXICON',NULL,NULL,NULL),(104,1,'Hỏi nhanh anh em làm phần cứng: đo nhiệt độ trong phòng thì nên dùng DHT22 hay SHT31? DHT22 rẻ nhưng mình thấy thỉnh thoảng nhảy số, còn SHT31 ổn định hơn mà giá gấp 3. Đồ án kỳ này cần đo liên tục 24/7 nên mình đang phân vân. Ai từng dùng cả hai cho mình xin kinh nghiệm với 🙏 #IoT #CamBien',NULL,'public',NULL,NULL,0,8,4,0,'2026-09-21 12:33:09',NULL,NULL,'ACTIVE',0,'POSITIVE',0.781,'LEXICON',NULL,NULL,NULL),(105,1,'Timelapse 3 tiếng hàn lại toàn bộ mạch cảm biến sau khi bản cũ bị chập 😭 Lần này có thêm cầu chì và đi dây gọn hơn hẳn. Bài học xương máu: đo nguội trước khi cắm điện! #Electronics #HanMach','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P05.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P05.mp4',104,10,3,0,'2026-10-03 12:30:09',NULL,NULL,'ACTIVE',0,'NEGATIVE',-0.659,'LEXICON',NULL,NULL,NULL),(106,1,'Thử chụp phơi sáng khu giảng đường lúc 9h tối: chân máy, ISO 100, tốc độ 20 giây. Vệt đèn xe ngoài đường Võ Văn Ngân nhìn như dải lụa vậy. Mọi người góp ý giúp mình bố cục nhé! #NhiepAnh #PhoiSang','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P06.jpg','public','IMAGE',NULL,0,7,4,0,'2026-10-15 17:54:53',NULL,9,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(107,2,'Review cơm tấm sườn bì chả gần cổng sau trường: sườn nướng than thơm lừng, nước mắm pha vừa miệng, 35k một dĩa đầy đặn. Điểm trừ duy nhất là 12h trưa phải xếp hàng 10 phút. Chấm 8.5/10 🍚 #ReviewDoAn #ComTam','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P07.jpg','public','IMAGE',NULL,0,6,4,0,'2026-08-28 08:23:24',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(108,2,'Một vòng chợ đêm với 100k thì ăn được những gì? Bánh tráng nướng, xiên que, trà mãng cầu, bột chiên... no căng bụng mà vẫn dư tiền gửi xe 😆 Video ngắn cho bạn nào mới lên Sài Gòn chưa biết đi đâu ăn tối. #AnVat #SaiGon','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P08.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P08.mp4',79,9,5,0,'2026-09-10 08:22:32',NULL,NULL,'ACTIVE',0,'POSITIVE',0.707,'LEXICON',NULL,NULL,NULL),(109,2,'Chiều thứ bảy chẳng đi đâu, pha ấm trà rồi đọc nốt \"Rừng Na Uy\". Có những cuốn sách đọc lúc 20 tuổi thấm hơn hẳn lúc 16. Mọi người đang đọc gì thì gợi ý mình cuốn tiếp theo nha 📖 #DocSach #CuoiTuan','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P09.jpg','public','IMAGE',NULL,0,11,3,0,'2026-09-25 15:35:20',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(110,2,'2 ngày 1 đêm ở Đà Lạt với 1 triệu 2: xe giường nằm, homestay dorm, đồi chè Cầu Đất lúc 6h sáng. Lạnh run nhưng đáng từng đồng! Lịch trình chi tiết mình để dưới bình luận 🌲 #DaLat #DuLichTietKiem','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P10.jpg','public','IMAGE',NULL,0,11,4,0,'2026-10-12 21:52:50',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(111,3,'Chạy thử robot dò line cho giải sinh viên tháng sau. Đổi sang thuật toán PID nên vào cua mượt hơn hẳn, hết cảnh lắc qua lắc lại như tuần trước. Còn phải tinh chỉnh tốc độ đoạn đường thẳng nữa 💪 #Robotics #PID','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P11.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P11.mp4',14,9,5,0,'2026-08-30 11:55:39',NULL,1,'ACTIVE',0,'POSITIVE',0.6,'LEXICON',NULL,NULL,NULL),(112,3,'Buổi workshop đầu tiên cho thành viên mới: hơn 30 bạn tới, phòng chật kín! Hôm nay học Arduino cơ bản, nháy LED và đọc cảm biến siêu âm. Tuần sau là động cơ và driver, nhớ mang laptop nhé 🤖 #CLBRobotics #Workshop','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P12.jpg','public','IMAGE',NULL,0,13,4,0,'2026-09-08 21:04:15',NULL,1,'ACTIVE',0,'POSITIVE',0.53,'LEXICON',NULL,NULL,NULL),(113,3,'Cánh tay robot 4 bậc tự do gắp và phân loại khối màu, dùng camera và OpenCV. Lần đầu chạy đúng 10/10 lần, cả team hét lên giữa phòng lab 😂 #RobotArm #OpenCV','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P13.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P13.mp4',31,12,4,0,'2026-09-27 07:40:10',NULL,1,'ACTIVE',0,'POSITIVE',0.6,'LEXICON',NULL,NULL,NULL),(114,3,'GIẢI NHÌ! 🥈 Cảm ơn cả team đã thức trắng mấy đêm cuối để sửa mạch. Năm sau mình quay lại lấy giải nhất. Tự hào CLB Robotics HCMUTE! #Robotics #ThanhTich','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P14.jpg','public','IMAGE',NULL,0,5,5,0,'2026-10-10 21:35:59',NULL,1,'ACTIVE',0,'POSITIVE',0.94,'LEXICON',NULL,NULL,NULL),(115,4,'Phác wireframe trên giấy trước rồi mới mở Figma: cách này giúp mình bớt sa vào chỉnh màu, chỉnh font quá sớm. Đây là luồng đặt lịch khám cho đồ án môn Tương tác người máy ✏️ #UIUX #Wireframe','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P15.jpg','public','IMAGE',NULL,0,18,4,0,'2026-09-03 21:28:17',NULL,NULL,'ACTIVE',0,'POSITIVE',0.447,'LEXICON',NULL,NULL,NULL),(116,4,'Speed design: giao diện app đặt món cho căng tin trường, ngồi Figma liền 3 tiếng mới xong 😅. Mọi người vote giúp mình nên giữ tông cam hay đổi sang xanh lá nha! #Figma #UIDesign','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P16.jpg','public','IMAGE',NULL,0,16,4,0,'2026-09-19 22:20:47',NULL,6,'ACTIVE',0,'POSITIVE',0.53,'LEXICON',NULL,NULL,NULL),(117,4,'Cuối tuần tạm cất laptop, vẽ màu nước lại cho đỡ nhớ tay. Vẽ góc phố có hàng bông giấy gần nhà. Lâu rồi mới vẽ nên màu hơi loang, nhưng vui là được 🎨 #MauNuoc #Ve','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P17.jpg','public','IMAGE',NULL,0,9,3,0,'2026-10-08 17:53:56',NULL,NULL,'ACTIVE',0,'POSITIVE',0.894,'LEXICON',NULL,NULL,NULL),(118,6,'Ma trận LED 16x16 tự hàn, điều khiển bằng Arduino, nháy theo nhạc. Mất 2 tối hàn 256 bóng LED, đau lưng nhưng nhìn thành quả là quên hết ✨ #Arduino #LED #Maker','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P18.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P18.mp4',124,11,4,0,'2026-09-04 11:25:02',NULL,1,'ACTIVE',0,'NEUTRAL',-0.243,'LEXICON',NULL,NULL,NULL),(119,6,'Góc maker mới dọn lại: Raspberry Pi chạy home server, mỏ hàn, đồng hồ đo và một rổ linh kiện \"chắc sẽ dùng tới\". Ai muốn ghé chơi nghịch đồ thì inbox mình 🔧 #RaspberryPi #MakerSpace','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P19.jpg','public','IMAGE',NULL,0,7,3,1,'2026-09-22 13:08:42',NULL,NULL,'ACTIVE',0,'POSITIVE',0.447,'LEXICON',NULL,NULL,NULL),(120,6,'Timelapse in 3D vỏ hộp cho mạch cảm biến: 4 tiếng in thu gọn còn hơn 1 phút. Nhựa PLA màu xanh dương nhìn khá xịn so với hộp nhựa mua ngoài 😎 #3DPrinting #Maker','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P20.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P20.mp4',82,5,4,0,'2026-10-06 10:33:28',NULL,1,'ACTIVE',0,'POSITIVE',0.868,'LEXICON',NULL,NULL,NULL),(121,7,'Học kỳ mới, góc học tập mới, toàn màu hồng 🎀 Có góc học tập dễ thương là có động lực ngồi vào bàn. Mấy món này mua online tổng chưa tới 300k nha! #GocHocTap #Pastel','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P21.jpg','public','IMAGE',NULL,0,9,4,0,'2026-09-01 17:44:36',NULL,NULL,'ACTIVE',0,'POSITIVE',0.905,'LEXICON',NULL,NULL,NULL),(122,7,'Năm 3 rồi mới hiểu: không cần thân với tất cả mọi người, chỉ cần vài người bạn thật lòng là đủ. Bớt so sánh, bớt để ý ai nói gì sau lưng, tập trung học và làm điều mình thích. Ai đang thấy mệt vì các mối quan hệ thì nhớ ưu tiên bản thân trước nha 💗 #TamSu #SinhVien',NULL,'public',NULL,NULL,0,10,4,0,'2026-09-16 20:43:12',NULL,NULL,'ACTIVE',0,'POSITIVE',0.447,'LEXICON',NULL,NULL,NULL),(123,7,'Hôm nay được tặng một bó cẩm tú cầu hồng vì... qua môn Kinh tế vi mô 😂 Nhỏ thôi nhưng vui cả ngày. Cảm ơn bạn thân nhé! #Hoa #NiemVuiNho','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P23.jpg','public','IMAGE',NULL,0,6,3,0,'2026-10-11 08:39:09',NULL,NULL,'ACTIVE',0,'POSITIVE',0.98,'LEXICON',NULL,NULL,NULL),(124,8,'5 điều mình ước được biết khi mới chơi CTF:\n1. Đọc kỹ đề, flag hay nằm ngay trong gợi ý.\n2. Học Linux cơ bản trước khi học tool.\n3. Ghi chép lại từng bài đã giải, sau này đỡ mất công tra lại.\n4. Chơi theo team, đừng chơi một mình.\n5. Kẹt quá 2 tiếng thì đọc writeup, không có gì phải ngại.\nAi mới bắt đầu thì tham gia giải nội bộ của nhóm cuối tháng nhé! #CTF #CyberSecurity',NULL,'public',NULL,NULL,0,9,4,0,'2026-08-26 18:01:31',NULL,5,'ACTIVE',0,'POSITIVE',0.852,'LEXICON',NULL,NULL,NULL),(125,8,'Chưa tới 1 phút để bật xác thực 2 lớp và passkey cho tài khoản. Mật khẩu mạnh tới đâu cũng có thể bị lộ, có thêm lớp thứ hai thì kẻ gian có mật khẩu cũng không vào được. UTErSpace cũng hỗ trợ đăng nhập bằng vân tay rồi đó, vào Cài đặt → Bảo mật để bật nhé 🔐 #BaoMat #2FA #Passkey','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P25.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P25.mp4',55,11,3,0,'2026-09-20 22:47:33',NULL,5,'ACTIVE',0,'NEGATIVE',-0.371,'LEXICON',NULL,NULL,NULL),(126,8,'⚠️ CẢNH BÁO: dạo này có nhiều tin \"tuyển thực tập sinh IT, lương 8 triệu, làm online\" gửi qua Zalo, bắt đóng phí giữ chỗ 500k hoặc cài file .apk lạ. Đây là LỪA ĐẢO. Công ty thật không bao giờ thu phí ứng viên. Thấy tin như vậy thì báo cáo bài viết và cảnh báo bạn bè giúp mình nhé. #CanhBao #LuaDao',NULL,'public',NULL,NULL,0,9,4,0,'2026-10-14 14:45:54',NULL,5,'ACTIVE',0,'NEGATIVE',-0.832,'LEXICON',NULL,NULL,NULL),(127,9,'Ký họa nhà phố cũ trên đường Phan Đình Phùng. Mấy căn nhà kiểu Pháp này ngày càng ít đi, mình muốn vẽ lại hết trước khi chúng bị thay bằng nhà kính 🏠✏️ #KyHoa #UrbanSketch','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P27.jpg','public','IMAGE',NULL,0,11,4,0,'2026-08-29 14:19:49',NULL,3,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(128,9,'Mô hình nhà ở xã hội có vườn trên mái, làm hết 2 tuần với bìa formex và rêu khô. Ý tưởng chính: mỗi tầng có một khoảng xanh chung cho hàng xóm gặp nhau 🌿 #KienTrucXanh #MoHinh','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P28.jpg','public','IMAGE',NULL,0,5,4,0,'2026-09-17 13:49:10',NULL,3,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(129,9,'Ban công 3m² của phòng trọ sau 6 tháng chăm cây: trầu bà, lưỡi hổ, một chậu húng quế để nấu ăn. Không gian nhỏ vẫn có thể xanh được 🌱 #CayXanh #PhongTro','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P29.jpg','public','IMAGE',NULL,0,3,4,0,'2026-10-09 11:30:56',NULL,NULL,'ACTIVE',0,'POSITIVE',0.447,'LEXICON',NULL,NULL,NULL),(130,15,'View từ văn phòng tầng 18 ở Quận 1. Tháng đầu đi thực tập, sáng nào cũng đứng đây uống cà phê 5 phút trước khi mở laptop. Cố lên bản thân ơi 💼 #ThucTap #Fintech','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P30.jpg','public','IMAGE',NULL,0,10,4,0,'2026-09-12 14:48:29',NULL,NULL,'ACTIVE',0,'POSITIVE',0.447,'LEXICON',NULL,NULL,NULL),(131,15,'Tổng kết 1 tháng thực tập fintech:\n- Viết test còn lâu hơn viết code, và điều đó là bình thường.\n- Hỏi sớm luôn tốt hơn tự mò 2 ngày.\n- Đọc code cũ của công ty là kỹ năng quan trọng không kém viết code mới.\n- Không ai mong intern biết hết, chỉ mong bạn tiến bộ mỗi tuần.\nBạn nào sắp đi thực tập có câu hỏi gì thì cứ bình luận, mình trả lời hết! #ThucTap #KinhNghiem',NULL,'public',NULL,NULL,0,6,4,0,'2026-10-02 17:25:24',NULL,NULL,'ACTIVE',0,'POSITIVE',0.962,'LEXICON',NULL,NULL,NULL),(132,16,'Bản phác thảo đầu tiên cho bộ sưu tập tốt nghiệp \"Áo dài đương đại\", lấy cảm hứng từ gạch bông Sài Gòn. Mình định