hi','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P56.jpg','public','IMAGE',NULL,0,6,3,0,'2026-10-03 12:44:24',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(157,24,'Hướng dẫn tự thay nhớt xe tay ga trong 5 phút, tiết kiệm được 50k tiền công. Nhớ chọn đúng loại nhớt theo sổ tay xe và vặn ốc xả với lực vừa phải thôi! 🛵 #XeMay #BaoDuong','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P57.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P57.mp4',33,5,4,0,'2026-08-31 07:30:54',NULL,NULL,'ACTIVE',0,'POSITIVE',0.53,'LEXICON',NULL,NULL,NULL),(158,24,'Khoang động cơ của chiếc Toyota đời 2005 ở gara anh khóa trên. Xe 20 năm tuổi mà máy vẫn êm ru, nhờ chủ xe bảo dưỡng đúng hạn 🔧 #OTo #DongCo','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P58.jpg','public','IMAGE',NULL,0,6,3,0,'2026-09-21 12:33:25',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(159,24,'Chạy thử xe tiết kiệm nhiên liệu mà nhóm tự chế cho cuộc thi sinh viên: 1 lít xăng chạy được hơn 200km trên đường thử của khoa 😱 Còn tối ưu thêm khí động học nữa! #XeTietKiemNhienLieu #CokhiOto','https://res.cloudinary.com/yjjoybu5/video/upload/so_1,q_auto/uterspace_seed/posts/P59.jpg','public','VIDEO','https://res.cloudinary.com/yjjoybu5/video/upload/uterspace_seed/posts/P59.mp4',37,9,5,0,'2026-10-12 22:13:35',NULL,NULL,'ACTIVE',0,'NEGATIVE',-0.351,'LEXICON',NULL,NULL,NULL),(160,26,'Buổi offline đầu tiên của CLB Sách học kỳ này: 25 bạn, 1 quán cà phê và 2 tiếng bàn luận về \"Đắc nhân tâm\". Cảm ơn mọi người đã đến đông vui như vậy! ☕📖 #CLBSach #Offline','https://res.cloudinary.com/yjjoybu5/image/upload/q_auto/uterspace_seed/posts/P60.jpg','public','IMAGE',NULL,0,7,4,0,'2026-09-04 07:32:30',NULL,NULL,'ACTIVE',0,'POSITIVE',0.905,'LEXICON',NULL,NULL,NULL),(161,26,'📢 Sách của tháng 10: \"Hai số phận\" (Jeffrey Archer). Thảo luận lúc 19h thứ năm cuối tháng tại phòng A3-204. Bạn nào chưa có sách thì CLB cho mượn 5 cuốn, inbox mình đăng ký trước nha! #CLBSach #SachThang10',NULL,'public',NULL,NULL,0,9,4,0,'2026-10-09 09:34:02',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(162,28,'IELTS Writing Task 2: 3 lỗi khiến bạn kẹt ở band 6.0\n1. Mở bài chép lại đề, chưa paraphrase.\n2. Mỗi đoạn thân bài có ý chính nhưng thiếu ví dụ cụ thể.\n3. Lạm dụng từ nối như \"Moreover\", \"Furthermore\" ở đầu mọi câu.\nThứ bảy này mình chữa bài miễn phí cho 5 bạn đầu tiên, gửi bài qua tin nhắn nhé ✍️ #IELTS #Writing',NULL,'public',NULL,NULL,0,10,4,0,'2026-10-18 13:50:36',NULL,4,'ACTIVE',0,'NEGATIVE',-0.447,'LEXICON',NULL,NULL,NULL),(163,14,'Nhìn lịch học từ Thứ 2 đến Thứ 6 phủ kín các môn AI, IoT, Cloud computing và Information Security là biết tuần mới thật bận rộn rồi! Cùng cố gắng học tập thật tốt thôi các UTEr ơi! 📚💻✨ #HCMUTE #SinhVien #UTErSpace','https://res.cloudinary.com/yjjoybu5/image/upload/v1792373388/uterspace_uploads/posts/bb6lhvgpsazgzo6r4fan.png','friends','IMAGE',NULL,0,0,0,0,'2026-10-19 08:29:48',NULL,NULL,'ACTIVE',1,'POSITIVE',0.85,'AI','PANORAMA',NULL,NULL),(164,4,'lộ',NULL,'public',NULL,NULL,0,0,0,0,'2026-10-19 10:22:46',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'LEXICON',NULL,NULL,NULL),(165,1,'model mới','https://res.cloudinary.com/yjjoybu5/image/upload/v1792384217/uterspace_uploads/posts/uy8pgc9kfkjw0nbztaay.jpg','public','IMAGE',NULL,0,1,0,0,'2026-10-19 11:30:18',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'AI','PANORAMA',NULL,NULL),(166,1,'ảnh 3d',NULL,'public',NULL,NULL,0,0,0,0,'2026-10-19 11:35:18',NULL,NULL,'ACTIVE',0,'NEUTRAL',0,'AI','MODEL3D','https://res.cloudinary.com/yjjoybu5/image/upload/v1792384516/uterspace_uploads/models/cb1ytygnwd3xbb0yoz5a.glb',NULL),(167,1,'có ai biết mua những cái này ở đâu không vậy',NULL,'public',NULL,NULL,0,0,0,0,'2026-10-23 11:08:25',119,NULL,'ACTIVE',0,'NEUTRAL',0,'AI',NULL,NULL,NULL);
